import datetime

import re

import json

def ctl_cents(amount):
    text = str(amount).strip()
    if not re.fullmatch(r'[0-9]+(?:\.[0-9]{1,2})?', text):
        return ''
    parts = text.split('.')
    cents = int(parts[0]) * 100 + int((parts[1] if len(parts) > 1 else '').ljust(2, '0'))
    return str(cents) if cents > 0 else ''

