        if re.fullmatch(r'[-+]?[0-9]+(?:[.,][0-9]*)?', text):
            return ctl_cents(text)
        return text
    if re.fullmatch(r'[0-9]{4}-[0-9]{1,2}-[0-9]{1,2}.*', text):
        try:
            return datetime.date.fromisoformat(text).isoformat()
        except Exception:
            return ''
    return text

