import re
try:
    text = vars.get('debt_text')
    if not isinstance(text, str) or not text.strip():
        raise ValueError('reading')
    months = ['Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
    def date_speech(match):
        day, month, year = match.groups()
        return str(int(day)) + ' ' + months[int(month) - 1] + ' ' + year
    text = re.sub(r'\b(\d{2})\.(\d{2})\.(\d{4})\b', date_speech, text)
    def amount_speech(match):
        whole, fraction, currency = match.groups()
        fraction = fraction or ''
        if len(fraction) > 2 and any(ch != '0' for ch in fraction[2:]):
            raise ValueError('precision')
        fraction = (fraction + '00')[:2]
        minor = int(fraction)
        unit = 'kuruş' if currency == 'Türk Lirası' else ('peni' if currency == 'İngiliz Sterlini' else 'sent')
        return whole + ' ' + currency + ((' ' + str(minor) + ' ' + unit) if minor else '')
    text = re.sub(r'\b(\d+)(?:\.(\d+))? (Türk Lirası|İngiliz Sterlini|Dolar|Euro)\b', amount_speech, text)
    digits = {'0': 'sıfır', '1': 'bir', '2': 'iki', '3': 'üç', '4': 'dört', '5': 'beş', '6': 'altı', '7': 'yedi', '8': 'sekiz', '9': 'dokuz'}
    def ending_speech(match):
        return 'Sonu ' + ' '.join(digits[ch] for ch in match.group(1) if ch.isdigit()) + ' ile biten'
    text = re.sub(r'Sonu ([0-9 ]+) ile biten', ending_speech, text)
    vars['debt_speech'] = text
    vars['debt_speech_status'] = 'ready'
except Exception:
    vars['debt_speech_status'] = 'error'

